155				data := buildSettleWindowBackup(t, t0, settleWindowOpts{
156					approved: approved, actualFee: 0, settledAt: deadline.Add(-time.Nanosecond),
157				})
158				w2, err := restoreAt(data, t0.Add(48*time.Hour))
159				if err != nil {
160					t.Fatalf("zero-fee in-window settle: %v", err)
161				}
162				r, _ := w2.Request("u1", "late")
163				if r.State != RequestSettled || r.ActualFee != 0 {
164					t.Fatalf("zero-fee settled request = %+v", r)
165				}
166				// 实际费用为零：预留已全额退回，策略已花费总额为零。
167				if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
168					t.Fatalf("balance = %+v, want full refund {100 0}", bal)
169				}
170				if pv, _ := w2.Policy("p"); pv.SpentTotal != 0 {
171					t.Fatalf("spent total = %d, want 0", pv.SpentTotal)
172				}
173			})
174		}
175	}
