177	// TestRestoreSettledHistoryPreservedLongAfterRestore 验证很久以后恢复时，期限内
178	// 已完成的结算仍保持已结算：实际费用、结算时间、余额、策略已花费总额与既有
179	// 账本原样保留，不追加退款或超时记录。
180	func TestRestoreSettledHistoryPreservedLongAfterRestore(t *testing.T) {
181		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
182		settledAt := t0.Add(90 * time.Minute) // 直接受理路径截止 t0+2h 之内
183		data := buildSettleWindowBackup(t, t0, settleWindowOpts{actualFee: 12, settledAt: settledAt})
184	
185		w2, err := restoreAt(data, t0.Add(30*24*time.Hour))
186		if err != nil {
187			t.Fatalf("legal settled history must restore long after deadline: %v", err)
188		}
189		r, _ := w2.Request("u1", "late")
190		if r.State != RequestSettled {
191			t.Fatalf("state = %v, want settled", r.State)
192		}
193		if r.ActualFee != 12 || !r.SettledAt.Equal(settledAt) {
194			t.Fatalf("settled history changed: fee %d at %v", r.ActualFee, r.SettledAt)
195		}
196		if !r.ReserveExpiredAt.IsZero() {
197			t.Fatalf("settled request must not gain a reserve-expired time: %v", r.ReserveExpiredAt)
198		}
199		// 初始 100：实际扣 12，退回差额 8。
200		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 88, Reserved: 0}) {
201			t.Fatalf("balance = %+v, want {88 0}", bal)
202		}
203		if pv, _ := w2.Policy("p"); pv.ReservedTotal != 0 || pv.SpentTotal != 12 {
204			t.Fatalf("policy totals = reserved %d spent %d, want 0/12", pv.ReservedTotal, pv.SpentTotal)
205		}
206		// 既有账本只有原结算记录，未因很久以后恢复而追加退款或超时记录。
207		led := w2.Ledger()
208		if len(led) != 1 || led[0].Kind != LedgerSettle || led[0].Amount != 12 {
209			t.Fatalf("ledger = %+v, want only the original settle entry", led)
210		}
211	}
