282	// TestRestoreSettleWindowSubSecondAndTimezoneInsensitive 验证时间比较依据保存
283	// 的完整时刻：纳秒精度保留，且不同时区表示的同一时刻判断一致。
284	func TestRestoreSettleWindowSubSecondAndTimezoneInsensitive(t *testing.T) {
285		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
286		deadline := t0.Add(2 * time.Hour)
287		loc := time.FixedZone("east", 5*60*60)
288	
289		// 截止前一纳秒，换成 +05:00 时区表示：仍是同一瞬间，必须接受。
290		before := deadline.Add(-time.Nanosecond).In(loc)
291		if before.Equal(deadline) {
292			t.Fatal("test setup: timezone conversion collapsed the instant")
293		}
294		data := buildSettleWindowBackup(t, t0, settleWindowOpts{actualFee: 20, settledAt: before})
295		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
296			t.Fatalf("same instant in a different timezone must restore: %v", err)
297		}
298	
299		// 截止时刻本身换时区表示：仍是同一瞬间，必须拒绝。
300		atDeadline := deadline.In(loc)
301		data = buildSettleWindowBackup(t, t0, settleWindowOpts{actualFee: 20, settledAt: atDeadline})
302		assertSettleWindowRejected(t, data, t0.Add(48*time.Hour))
303	}
