305	// TestRestoreSettledWithTimeoutDisabledHasNoSettleDeadline 验证关闭预留超时的
306	// 请求沿用原有结算规则：没有截止时刻，很久以后结算仍合法，不人为增加期限。
307	func TestRestoreSettledWithTimeoutDisabledHasNoSettleDeadline(t *testing.T) {
308		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
309		disable := func(_ *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
310			p.MaxReserveDuration = 0
311		}
312		// 结算时刻远在预留之后，且不携带任何截止时刻：照常恢复。
313		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
314			actualFee: 20, settledAt: t0.Add(24 * time.Hour), mutate: disable,
315		})
316		// builder 默认写了 2h 的预留计时；关闭超时时必须清空，保持备份自洽。
317		var b backupV1
318		if err := json.Unmarshal(data, &b); err != nil {
319			t.Fatal(err)
320		}
321		b.Requests[0].ReserveDuration = durationJSON(0)
322		b.Requests[0].ReserveDeadline = timeJSON(time.Time{})
323		fixed, err := json.Marshal(&b)
324		if err != nil {
325			t.Fatal(err)
326		}
327		w2, err := restoreAt(fixed, t0.Add(30*24*time.Hour))
328		if err != nil {
329			t.Fatalf("settle with reserve timeout disabled must have no deadline: %v", err)
330		}
331		r, _ := w2.Request("u1", "late")
332		if r.State != RequestSettled || !r.ReserveDeadline.IsZero() {
333			t.Fatalf("timeout-disabled settled request = %+v", r)
334		}
335	}
