337	// TestRestoreSettledUnaffectedByLaterSessionPolicyLifecycle 验证只要结算在预留
338	// 有效期内合法完成，申请会话后来到期或被吊销、策略结束或被停用，都不应把已
339	// 合法完成的结算变成错误历史。
340	func TestRestoreSettledUnaffectedByLaterSessionPolicyLifecycle(t *testing.T) {
341		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
342		// 直接受理预留 [t0, t0+2h)；在 t0+1h 结算，此时会话、策略均已结束。
343		sessionExpired := func(_ *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
344			s.ExpiresAt = timeJSON(t0.Add(30 * time.Minute))
345		}
346		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
347			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: sessionExpired,
348		})
349		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
350			t.Fatalf("session expiring before a legal settle must not invalidate history: %v", err)
351		}
352	
353		sessionRevoked := func(_ *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
354			s.ExpiresAt = timeJSON(t0.Add(24 * time.Hour))
355			s.Revoked = true
356		}
357		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
358			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: sessionRevoked,
359		})
360		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
361			t.Fatalf("revoked application session must not invalidate a settled reservation: %v", err)
362		}
363	
364		// 策略在结算前已结束，但策略结束不缩短预留：截止 t0+2h 前的结算仍合法。
365		policyEnded := func(_ *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
366			p.EndsAt = timeJSON(t0.Add(30 * time.Minute))
367		}
368		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
369			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: policyEnded,
370		})
371		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
372			t.Fatalf("policy ending before deadline must not shorten the reserve window: %v", err)
373		}
374	
375		// 策略后来被停用：已合法完成的结算照常恢复。
376		policyDeactivated := func(_ *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
377			p.Deactivated = true
378			p.DeactivatedAt = timeJSON(t0.Add(90 * time.Minute))
379			p.DeactivatorAccountID = "payer"
380			p.DeactivateReason = "stopped"
381		}
382		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
383			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: policyDeactivated,
384		})
385		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
386			t.Fatalf("later policy deactivation must not invalidate a legal settle: %v", err)
387		}
388	}
