390	// TestRestoreRejectsBackupWhenAnySettledRequestOutOfWindow 验证同一备份中只要
391	// 有一笔已结算请求违反预留期限，整个恢复失败、不返回可用钱包，即使另一笔
392	// 已结算请求完全合法。
393	func TestRestoreRejectsBackupWhenAnySettledRequestOutOfWindow(t *testing.T) {
394		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
395		// 两笔零实际费用的已结算请求：late 恰在截止时刻（非法），ok 在窗口内。
396		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
397			actualFee: 0, settledAt: t0.Add(2 * time.Hour), // late：恰在截止 t0+2h
398		})
399		var b backupV1
400		if err := json.Unmarshal(data, &b); err != nil {
401			t.Fatal(err)
402		}
403		b.Requests = append(b.Requests, requestBackupV1{
404			PolicyID: "p", RequestID: "ok", AccountID: "u1", PayerAccountID: "payer",
405			SessionID: "s1", Operation: "charge", Payee: "shop",
406			EstimatedFee: 20, ActualFee: 0, State: int(RequestSettled),
407			CreatedAt: timeJSON(t0), SettledAt: timeJSON(t0.Add(time.Hour)),
408			ReservedAt: timeJSON(t0), ReserveDuration: durationJSON(2 * time.Hour),
409			ReserveDeadline: timeJSON(t0.Add(2 * time.Hour)),
410		})
411		corrupt, err := json.Marshal(&b)
412		if err != nil {
413			t.Fatal(err)
414		}
415		assertSettleWindowRejected(t, corrupt, t0.Add(48*time.Hour))
416	}
417	
418	// TestRestoreLegalExportWithTimeoutSettleRoundTrips 端到端验证当前版本合法导出
419	// 文本继续兼容：在真实钱包中于预留窗口内结算，导出后于很久以后恢复，已结算
420	// 状态、金额与账本完整保留。
421	func TestRestoreLegalExportWithTimeoutSettleRoundTrips(t *testing.T) {
422		w, c := setupTimeout(t, time.Hour)
423		if _, err := w.Apply(timeoutApply()); err != nil { // r1 预留于 t0，截止 t0+1h
424			t.Fatal(err)
425		}
426		c.t = c.t.Add(30 * time.Minute)
427		if _, err := w.Settle("u1", "r1", 7); err != nil { // 窗口内结算
428			t.Fatal(err)
429		}
430		data, err := w.Export()
431		if err != nil {
432			t.Fatal(err)
433		}
434		w2, err := restoreAt(data, c.t.Add(30*24*time.Hour))
435		if err != nil {
436			t.Fatalf("legal in-window settled export must restore long after: %v", err)
437		}
438		r, _ := w2.Request("u1", "r1")
439		if r.State != RequestSettled || r.ActualFee != 7 {
440			t.Fatalf("restored settled request = %+v", r)
441		}
442		if l1, l2 := len(w.Ledger()), len(w2.Ledger()); l1 != l2 {
443			t.Fatalf("ledger entries added on restore: source %d restored %d", l1, l2)
444		}
445		if n := countKind(w2.Ledger(), LedgerReservationExpiration); n != 0 {
446			t.Fatalf("settled request gained timeout entries on restore: %d", n)
447		}
448		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 93, Reserved: 0}) {
449			t.Fatalf("balance = %+v, want {93 0}", bal)
450		}
