		t.Fatalf("zero-fee settled request = %+v", r)
	}
}

// itoa 是测试本地使用的简易整数格式化，避免为单个用例名引入 strconv。
func itoa(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

